  "combobox/Basic": "import * as Combobox from '@/ui/combobox'\n\nconst preview = (model, h: HtmlBuilder<PreviewMessage>) =>\r\n    Combobox.combobox(\r\n      {\r\n        model: model.combobox,\r\n        maybeSelectedValue: model.selectedComboboxValue,\r\n        restingInputValue: Option.match(model.selectedComboboxValue, {\r\n          onNone: () => '',\r\n          onSome: (value) =>\r\n            ({ next: 'Next.js', svelte: 'SvelteKit', nuxt: 'Nuxt.js' })[\r\n              value as 'next' | 'svelte' | 'nuxt'\r\n            ] ?? value,\r\n        }),\r\n        toParentMessage: (message) => State.GotComboboxMessage({ message }),\r\n        items: [\r\n          { value: 'next', label: 'Next.js' },\r\n          { value: 'svelte', label: 'SvelteKit' },\r\n          { value: 'nuxt', label: 'Nuxt.js' },\r\n        ],\r\n        itemToValue: (item) => item.value,\r\n        itemToLabel: (item) => item.label,\r\n        placeholder: 'Select framework…',\r\n      },\r\n      h,\r\n    )\n",
  "combobox/Multiple": "import * as Combobox from '@/ui/combobox'\n\nconst preview = (model, h: HtmlBuilder<Msg>) =>\r\n          stack(\r\n            [\r\n              comboboxPreview(model, {}, h),\r\n              row(\r\n                [\r\n                  Badge.badge({ children: ['Next.js'] }, h),\r\n                  Badge.badge(\r\n                    { variant: 'secondary', children: ['SvelteKit'] },\r\n                    h,\r\n                  ),\r\n                ],\r\n                '',\r\n                h,\r\n              ),\r\n            ],\r\n            '',\r\n            h,\r\n          )\n",
  "combobox/Clear Button": "import * as Combobox from '@/ui/combobox'\n\nconst preview = (model, h: HtmlBuilder<Msg>) =>\r\n          row(\r\n            [\r\n              comboboxPreview(model, { clear: true }, h),\r\n              Button.button(\r\n                {\r\n                  variant: 'ghost',\r\n                  size: 'sm',\r\n                  onClick: clicked,\r\n                  children: ['Clear'],\r\n                },\r\n                h,\r\n              ),\r\n            ],\r\n            '',\r\n            h,\r\n          )\n",
